			super.interpolate(index, nextIndex, t, duration, target);
			const x = target[0];
			const y = target[1];
			const z = target[2];
			const w = target[3];
			const invLen = 1 / Math.sqrt(x * x + y * y + z * z + w * w);
			target[0] *= invLen;
			target[1] *= invLen;
			target[2] *= invLen;
			target[3] *= invLen;
