/** @internal */
const anisotropyBit = createAnisotropyBit(false, false);
/** @internal */
const anisotropyTextureBit = createAnisotropyBit(true, false);
/** @internal */
const anisotropyTangentBit = createAnisotropyBit(false, true);
/** @internal */
const anisotropyTextureTangentBit = createAnisotropyBit(true, true);
