//#region src/core/shader/bits/emissiveBit.ts
/**
* Field and texture names must match `EmissivePropsClass` in `materials/utils/emissiveProps.ts`
* @internal
*/
const emissiveBit = {
	name: "emissive",
	textures: ["emissive"],
	bindings: { material: {
		emissive: "vec3<f32>",
		emissiveStrength: "f32"
	} },
	gpu: { fragment: { material: `
  emissive = material.emissive * material.emissiveStrength;
  let emissiveTex = sampleEmissive(input.vUV).rgb;
  emissive *= pow(emissiveTex, vec3<f32>(2.2));
` } },
	gl: { fragment: { material: `
  emissive = material.emissive * material.emissiveStrength;
  vec3 emissiveTex = sampleEmissive(vUV).rgb;
  emissive *= pow(emissiveTex, vec3(2.2));
` } }
};

//#endregion
//#region src/materials/utils/createFeaturePropsClass.ts
/**
* Builds the class behind a feature-props object such as `material.clearcoat`; lane setters compare
* with `Math.fround(value)`, or re-setting an inexact value like 0.3 would queue an upload each time
* @internal
*/
function createFeaturePropsClass(schema) {
	const bindings = Object.entries(schema);
	const colourBindings = bindings.filter(([, binding]) => binding.kind === "colour");
	class FeatureProps {
		_material;
		_data;
		_colours = Object.create(null);
		_tints = Object.create(null);
		constructor(material) {
			this._material = material;
			this._data = material.data;
			for (const [name, binding] of colourBindings) {
				const view = this._data[binding.field].subarray(0, 3);
				this._colours[name] = view;
				this._tints[name] = Color.shared.setValue([
					linearToSrgb(view[0]),
					linearToSrgb(view[1]),
					linearToSrgb(view[2])
				]).toNumber();
			}
		}
	}
	for (const [name, binding] of bindings) {
		let descriptor;
		switch (binding.kind) {
			case "lane": {
				const { field, lane } = binding;
				descriptor = {
					get() {
						return this._data[field][lane];
					},
					set(value) {
						const view = this._data[field];
						if (view[lane] === Math.fround(value)) return;
						view[lane] = value;
						this._material.update();
					}
				};
				break;
			}
			case "scalar": {
				const { field } = binding;
				descriptor = {
					get() {
						return this._data[field];
					},
					set(value) {
						this._data[field] = value;
					}
				};
				break;
			}
			case "colour":
				descriptor = {
					get() {
						return this._tints[name];
					},
					set(value) {
						const colour = Color.shared.setValue(value);
						this._tints[name] = colour.toNumber();
						writeLinearRgb(this._colours[name], 0, colour);
						this._material.update();
					}
				};
				break;
			case "texture": {
				const { slot } = binding;
				descriptor = { get() {
					return this._material.textures[slot];
				} };
				if (!binding.readonly) descriptor.set = function(value) {
					this._material.textures[slot] = value;
				};
				break;
			}
		}
		descriptor.enumerable = true;
		descriptor.configurable = false;
		Object.defineProperty(FeatureProps.prototype, name, descriptor);
	}
	return FeatureProps;
}
/**
* Read a feature-props object back as a plain object of its props, such as the `clearcoat` options
* `clone` passes to the copy's constructor
*
* The names come from the prototype, where {@link createFeaturePropsClass} defines every prop of the
* schema as enumerable, so they can't drift from the getters. The instance's own fields
* (`_material`, `_data`, the colour views) aren't on the prototype, so they stay out. A `readonly`
* texture prop the group was built without reads `undefined`.
* @param props - An instance of a class {@link createFeaturePropsClass} built
* @returns Each prop's current value, by name
* @internal
*/
function readFeatureProps(props) {
	const values = {};
	for (const name of Object.keys(Object.getPrototypeOf(props))) values[name] = props[name];
	return values;
}

//#endregion
//#region src/materials/utils/emissiveProps.ts
/**
* Field and slot names here must match what `emissiveBit` declares
* @internal
*/
const EmissivePropsClass = createFeaturePropsClass({
	color: {
		kind: "colour",
		field: "emissive"
	},
	strength: {
		kind: "scalar",
		field: "emissiveStrength"
	},
	texture: {
		kind: "texture",
		slot: "emissive"
	}
});

