        let a2 = roughness * roughness * roughness * roughness;
        let d = NdotH * NdotH * (a2 - 1.0) + 1.0;
        let pdf = a2 / (PI * d * d) * 0.25;
        let solidAnglePerSample = 1.0 / (local.sampleCount * pdf + 1e-4);
