//#region src/init.ts
/** Loaded lazily, so a page downloads only the backend its renderer picks */
const backendLoaders = [{
	extension: {
		type: ExtensionType.WebGLLoader,
		name: "pixijs-3d"
	},
	load: () => import("./pixijs-3d-webgl.mjs")
}, {
	extension: {
		type: ExtensionType.WebGPULoader,
		name: "pixijs-3d"
	},
	load: () => import("./pixijs-3d-webgpu.mjs")
}];
addUniformParsers();
extensions.add(...backendLoaders);

